package main

import("fmt";"strings";"time";"github.com/gin-gonic/gin";"gorm.io/gorm")
func updateSchedule(db *gorm.DB) gin.HandlerFunc{return func(c *gin.Context){id:=channelID(c);if !hasPermission(db,c,id,"schedule"){return};var sid uint64;_,_=fmt.Sscan(c.Param("scheduleId"),&sid);var row ChannelSchedule;if db.Where("id=? AND channel_id=?",sid,id).First(&row).Error!=nil{c.JSON(404,gin.H{"message":"schedule not found"});return};var in struct{Title string `json:"title"`;ProgramID *uint64 `json:"programId"`;StartsAt *time.Time `json:"startsAt"`;EndsAt *time.Time `json:"endsAt"`;Status string `json:"status"`};if c.ShouldBindJSON(&in)!=nil{c.JSON(400,gin.H{"message":"invalid request body"});return};if strings.TrimSpace(in.Title)!=""{row.Title=strings.TrimSpace(in.Title)};if in.ProgramID!=nil{row.ProgramID=in.ProgramID};if in.StartsAt!=nil{row.StartsAt=*in.StartsAt};if in.EndsAt!=nil{row.EndsAt=in.EndsAt};if in.Status!=""{row.Status=strings.ToUpper(strings.TrimSpace(in.Status))};if err:=db.Save(&row).Error;err!=nil{c.JSON(500,gin.H{"message":"failed to update schedule"});return};c.JSON(200,row)}}
func deleteSchedule(db *gorm.DB) gin.HandlerFunc{return func(c *gin.Context){id:=channelID(c);if !hasPermission(db,c,id,"schedule"){return};var sid uint64;_,_=fmt.Sscan(c.Param("scheduleId"),&sid);if err:=db.Where("id=? AND channel_id=?",sid,id).Delete(&ChannelSchedule{}).Error;err!=nil{c.JSON(500,gin.H{"message":"failed to delete schedule"});return};c.Status(204)}}
func updateContent(db *gorm.DB) gin.HandlerFunc{return func(c *gin.Context){id:=channelID(c);if !hasPermission(db,c,id,"content"){return};var cid uint64;_,_=fmt.Sscan(c.Param("contentId"),&cid);var row ChannelContent;if db.Where("id=? AND channel_id=?",cid,id).First(&row).Error!=nil{c.JSON(404,gin.H{"message":"content not found"});return};var in struct{Status string `json:"status"`};if c.ShouldBindJSON(&in)!=nil{c.JSON(400,gin.H{"message":"invalid request body"});return};if in.Status!=""{row.Status=strings.ToUpper(strings.TrimSpace(in.Status))};if err:=db.Save(&row).Error;err!=nil{c.JSON(500,gin.H{"message":"failed to update content"});return};c.JSON(200,row)}}
